using UnityEngine;

namespace Game.World
{
    /// <summary>
    /// Every material the game uses, referenced from one asset. Runtime code builds buildings from
    /// primitives and picks materials from here, which also guarantees the toon shader ends up in the build.
    /// The asset is generated by the editor script ArtBuilder.
    /// </summary>
    [CreateAssetMenu(menuName = "Construction/Toon Palette")]
    public sealed class ToonPalette : ScriptableObject
    {
        [Header("Environment")]
        public Material grass;
        public Material dirt;
        public Material sea;
        public Material trunk;
        public Material leaves;
        public Material crate;
        public Material cone;
        public Material stone;
        public Material[] districtGround;   // top of each district's island, one tint per district

        [Header("Construction")]
        public Material[] walls;       // one per building plan
        public Material roof;
        public Material window;
        public Material door;
        public Material scaffold;
        public Material flag;

        [Header("Worker")]
        public Material skin;
        public Material hat;
        public Material shirt;
        public Material shirtHelper;
        public Material hammerHandle;
        public Material hammerHead;
        public Material eye;

        [Header("UI in world")]
        public Material barBack;
        public Material barFill;
        public Material marker;
        public Material energyFill;
        public Material energyLow;
    }
}
